// spec: specs/listing-page.md (1.1–1.2) · кейсы: .qa/tests/listing-page/LISTING-TURNOVER-01.md, -02.md
// seed: tests/seed.spec.ts (гость) · прод, только просмотр: страница шлёт POST increment_business_views — не-GET блокируются.
import { test, expect, Page } from '@playwright/test';

const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];
const LOAD = { timeout: 20_000 };
/** Объявления с заполненным «מחזור שנתי» (проверены 27.10). Если объявление снято с сайта — это данные, не баг. */
const WITH_TURNOVER = [
  '5832e079-87c7-49a8-9c24-97e7664dcba6',
  '7d6e4de2-0f49-43fb-8e80-38b7c314a61e',
  '23c080df-7b0e-452d-9861-5f6a90f745f9',
];
/** Объявление без «מחזור שנתי» (в блоке только «משך פעילות»). */
const WITHOUT_TURNOVER = '4d62fda8-629a-4ad5-9913-3f925cbbb1d1';

test.use({ serviceWorkers: 'block' });

async function openListing(page: Page, id: string) {
  await page.route('**/*', (route) =>
    SAFE_METHODS.includes(route.request().method()) ? route.fallback() : route.abort('blockedbyclient'),
  );
  await page.goto(`/businessdetail?id=${id}`);
  await expect(page.getByText('פרטים נוספים', { exact: true })).toBeVisible(LOAD);
}

/** Иконка dollar-sign (lucide) или символ «$» — не должно быть нигде на странице. */
async function expectNoDollar(page: Page) {
  await expect(page.locator('svg.lucide-dollar-sign'), 'иконки dollar-sign нет').toHaveCount(0);
  await expect(page.getByText('$'), 'символа «$» нет').toHaveCount(0);
}

test.describe('Страница объявления — «פרטים נוספים»', () => {
  for (const id of WITH_TURNOVER) {
    test(`«מחזור שנתי» — иконка ₪ вместо $ (${id.slice(0, 8)}) #dab8a7 @android @prod-safe`, async ({ page }) => {
      await openListing(page, id);

      const label = page.getByText('מחזור שנתי', { exact: true });
      await expect(label).toBeVisible();
      const tile = label.locator('..');
      const icon = tile.getByText('₪', { exact: true });
      await expect(icon, 'иконка «₪» в плитке «מחזור שנתי»').toBeVisible();
      await expect(tile.locator('svg.lucide-dollar-sign'), 'иконки $ в плитке нет').toHaveCount(0);
      await expect(tile.getByText(/^₪[\d,]+$/), 'значение «₪<сумма>»').toBeVisible();

      // Иконка над подписью, цвет — как у соседней иконки блока («משך פעילות»)
      const iconBox = await icon.boundingBox();
      const labelBox = await label.boundingBox();
      expect(iconBox!.y + iconBox!.height, 'иконка над подписью').toBeLessThanOrEqual(labelBox!.y + 1);
      const neighbourIcon = page.getByText('משך פעילות', { exact: true }).locator('..').locator('svg').first();
      const color = (l: typeof icon) => l.evaluate((el) => getComputedStyle(el).color);
      expect(await color(icon), 'цвет ₪ = цвет соседних иконок').toBe(await color(neighbourIcon));

      await expectNoDollar(page);
    });
  }

  test('Без «מחזור שנתי» — плитки нет; «הצג פרטים מתקדמים» раскрывает блок без $ #dab8a7 @android @prod-safe', async ({ page }) => {
    await openListing(page, WITHOUT_TURNOVER);
    await expect(page.getByText('מחזור שנתי', { exact: true }), 'плитки «מחזור שנתי» нет').toHaveCount(0);

    await page.getByRole('button', { name: 'הצג פרטים מתקדמים' }).click();
    await expect(page.getByRole('button', { name: 'הסתר פרטים מתקדמים' })).toHaveAttribute('aria-expanded', 'true');
    for (const field of ['הכנסות חודשיות', 'הוצאות חודשיות', 'ארנונה עסקית', 'מספר עובדים']) {
      await expect(page.getByText(field, { exact: true }), `поле «${field}»`).toBeVisible();
    }
    await expectNoDollar(page);
  });

  test('С «מחזור שנתי» — «הצג פרטים מתקדמים» раскрывает блок без $ #dab8a7 @android @prod-safe', async ({ page }) => {
    await openListing(page, WITH_TURNOVER[0]);
    await page.getByRole('button', { name: 'הצג פרטים מתקדמים' }).click();
    await expect(page.getByRole('button', { name: 'הסתר פרטים מתקדמים' })).toHaveAttribute('aria-expanded', 'true');
    for (const field of ['מחזור שנתי', 'הכנסות חודשיות', 'הוצאות חודשיות', 'ארנונה עסקית', 'מספר עובדים']) {
      await expect(page.getByText(field, { exact: true }), `поле «${field}»`).toBeVisible();
    }
    await expectNoDollar(page);
  });
});
